/** The brand mark for a site's domain, matching parent domains too ("en.wikipedia.org"). */
export function siteMark(domain: string): BrandMark | undefined {
  for (let d = domain.replace(/^www\./, ""); d.includes("."); d = d.slice(d.indexOf(".") + 1)) {
    const i = SITES[d];
    if (i !== undefined) return MARKS[i];
  }
  return undefined;
}

/** The brand mark for an app by its name, allowing editions ("Docker Desktop", "Discord PTB"). */
export function appMark(name: string): BrandMark | undefined {
  let n = name.toLowerCase().replace(/\.(app|exe)$/, "").trim();
  for (;;) {
    const i = APPS[n];
    if (i !== undefined) return MARKS[i];
    const cut = n.lastIndexOf(" ");
    if (cut < 0) return undefined;
    n = n.slice(0, cut);
  }
}
